j.GetAssetId = function(G, V)
    if not G or not V then
        return 0, false
    end
    local Z = V ..(":" .. G)
    local i = j.AssetCache[Z]
    if i then
        return i, true
    end
    local c = j.EggsNoIcons[G]
    if c then
        return c, true
    end
    local J, T = pcall(function()
        return y.FindItemImage(G, V)
    end)
    if not J or not T then
        j.AssetCache[Z] = 0
        return 0, false
    end
    local d = tonumber(string.match(T, "%d+")) or 0
    local u = false
    if d == 6937742258 then
        d = 0
        u = true
    end
    j.AssetCache[Z] = d
    return d, true, u
end
j.MakeAltFolder = function(G)
    if not G then
        warn("MakeAltFolder requires a userId!")
        return nil
    end
    local V = tostring(G) .. "_Plants"
    local Z = y.ReplicatedStorage:FindFirstChild(V)
    if Z then
        j.alt_Plants_Physical[G] = Z
        return Z
    end
    local i = Instance.new("Folder")
    i.Name = V
    i.Parent = y.ReplicatedStorage
    j.alt_Plants_Physical[G] = i
    return i
end
