H.TrowelLoop = function()
    if f.Is_MasterBusy() then
        H.UpdateTrowelStatus("\240\159\165\154 Paused: tasks in progress.")
        return false
    end
    if not H.trowel_is_running then
        H.UpdateTrowelStatus("\240\159\148\180 Not Running...")
        return false
    end
    local G = H.StringToVector3(J.trowel_saved_cframe)
    if not G then
        H.UpdateTrowelStatus("\240\159\148\180 Stopping: Location invalid...")
        H.trowel_is_running = false
        return false
    end
    local V = H.GetAllPlantsOnFarmForTrowel(G)
    if not V or # V == 0 then
        H.UpdateTrowelStatus("\240\159\148\180 Stopping: No plants to move...")
        H.trowel_is_running = false
        return false
    end
    local y = H.FindTrowelTool()
    if not y then
        H.UpdateTrowelStatus("\240\159\148\180 Stopping: No trowel found...")
        H.trowel_is_running = false
        return false
    end
    j.trowel_count_total_to_move = # V
    j.trowel_current_moved = 0
    local Z = 0
    H.UpdateTrowelStatus("\240\159\159\162 Active and running...")
    H.UpdateTrowelProgress(string.format("\240\159\148\132 <font color=\'#32CD32\'>Moving </font> %d/%d", j.trowel_current_moved, j.trowel_count_total_to_move))
    dJ()
    task.wait(.3)
    if not TJ(y) then
        return false
    end
    for V, i in ipairs(V) do
        if not H.trowel_is_running then
            H.UpdateTrowelStatus("\226\157\140 Stopped by user.")
            break
        end
        if f.Is_MasterBusy() then
            H.UpdateTrowelStatus("\226\143\184\239\184\143 Paused mid-process...")
            break
        end
        if not PJ(y) then
            H.UpdateTrowelStatus("\226\157\140 Tool not held. Equipping... ")
            dJ()
            task.wait(.3)
            TJ(y)
            Z = Z + 1
            task.wait(1)
            if Z > 15 then
                H.UpdateTrowelStatus("\240\159\148\180 Failed to hold tool after 15 tries.")
                break
            end
        end
        local c = H.PickUpPlantUsingTrowel(y, i)
        if not c then
            H.UpdateTrowelStatus("\226\157\140 Failed to pick up: " .. tostring(i.Name))
            continue
        end
        task.wait(.1)
        local J = H.PlacePlantUsingTrowel(y, i, G)
        if not J then
            H.UpdateTrowelStatus("\226\157\140 Failed to place: " .. tostring(i.Name))
            continue
        end
        j.trowel_current_moved = j.trowel_current_moved + 1
        H.UpdateTrowelStatus("\240\159\159\162 Success " .. tostring(i.Name))
        H.UpdateTrowelProgress(string.format("\240\159\148\132 <font color=\'#32CD32\'>Moving </font> %d/%d", j.trowel_current_moved, j.trowel_count_total_to_move))
        task.wait(.1)
    end
    dJ()
    if j.trowel_current_moved >= j.trowel_count_total_to_move then
        H.trowel_is_running = false
        H.UpdateTrowelStatus("\226\156\133 All plants moved. If nothing moved please make sure to set cframe again and inside your farm.")
    end
    H.UpdateTrowelProgress(string.format("\240\159\147\138 Last Moved %d/%d", j.trowel_current_moved, j.trowel_count_total_to_move))
    return true
end
