            task.wait(5)
            break
        end
        local i = {[1] = { name = "Team 1";
        data = A.Teams.GetTeam1();
        delay = d.customteams_team1_delay, enabled = true};
        [2] = { name = "Team 2", data = A.Teams.GetTeam2();
        delay = d.customteams_team2_delay, enabled = d.customteams_team2_enabled};
        [3] = { name = "Team 3";
        data = A.Teams.GetTeam3(), delay = d.customteams_team3_delay, enabled = d.customteams_team3_enabled};
        [4] = { name = "Team 4", data = A.Teams.GetTeam4();
        delay = d.customteams_team4_delay, enabled = d.customteams_team4_enabled}}
        local c = nil
        local J = 1
        for G = 0, 3, 1 do
            local V =((((y + G) - 1)) % 4) + 1
            local Z = i[V]
            if Z and(Z.enabled and(Z.data and # Z.data > 0)) then
                c = Z
                J = V
                y = V + 1
                break
            end
        end
        if not c then
            c = i[1]
            J = 1
        end
        if Z ~= J then
            j.SetDisablePickPlaceFor(3)
            G(string.format("[Switching] Swapping to %s...", c.name))
            if not j.UnEquipAllPets() then
                G("[Error] Failed to unequip " .. c.name)
