                task.wait(2)
                Z = nil
                continue
            else
                Z = J
                G(string.format("[Team Active] %s equipped.", c.name))
                task.wait(1)
            end
        else
            G(string.format("[Looping] Starting %s shift...", c.name))
        end
        h.StopTimer(V)
        h.StartTimer(V)
        local T = c.delay or 30
        local u = 0
        local q = os.clock()
        local g = 9
        while u < T and d.is_running_custom_teams do
            task.wait(1)
            u = u + 1
            if d.customteams_boosts_enabled then
                if h.IsTimeUp(q, g) then
                    q = os.clock()
                    r.ApplyBoostSelectedWithPetNames(d.customteams_boosts, d.customteams_boost_teamunits)
