                end
            end
            local y = h.GetTimerFormatted(V)
            local Z = T - u
            local j = string.format("[Running: %s]\nActive Time: %s\nSwitching in: %ds", c.name, y, Z)
            G(j)
        end
    end
    h.StopTimer(V)
    t.StopCustomTeams()
    G("System Stopped.")
end
