a.AutoStartEvents = function()
    if d.is_running_custom_teams then
        j.Notify("Starting teams system in 10s", 9)
        task.wait(10)
        t.StartCustomTeams()
    end
    if d.mut_system.is_ruuning then
        j.Notify("Auto resume pet mutation in 10s", 9)
        task.wait(10)
        t.StartThread()
        return
    end
    if d.mutation_machine_pro and d.mutation_machine_pro.enabled then
        j.Notify("Auto resume Mutation Machine Pro in 10s", 9)
        task.wait(10)
        s.StartThreadMutationMachinePro()
        return
    end
    if J.harvest_moon.auto_moon_machine_leveling then
        j.Notify("Auto resume Moon Machine leveling in 10s", 9)
        task.wait(10)
        if J.harvest_moon.auto_moon_machine_leveling then
            S.HarvestMoonPetMachine.StartLevelingHarvestMoonPetMachine()
            return
        end
    end
    if d.is_running then
        task.spawn(function()
            j.Notify("Auto resume hatching in 10s", 7)
            local G = 10
            while G > 0 do
                task.wait(1)
                if not d.is_running then
                    break
                end
                if not a.IsDataFullyLoaded() or not a.IsFarmFullyLoaded() then
                    continue
                end
                G = G - 1
                if G <= 1 then
                    j.StartHatchingSystem()
                    break
                end
            end
        end)
    end
end
